}

#[derive(serde::Serialize)]
struct NoteStateJs {
    input_notes: Vec<u8>,
    harmony_notes: Vec<u8>,
    borrowed_notes: Vec<u8>,
    chord_name: String,
    last_borrowed_from: String,
}

#[derive(serde::Serialize)]
