        order.sort_by_key(|&i| std::cmp::Reverse(u8::from(notes[i])));
        let mut arr = vec![0usize; notes.len()];
        for (slot, &idx) in order.iter().enumerate() {
            arr[idx] = slot;
        }
        self.last_arrangement_indices = arr;
    }

