            config,
            calibration: None,
            normalizer: None,
            calibration_profile: None,
            current_note: None,
            prev_rms: 0.0,
            cooldown_remaining: 0,
            ring_buffer: vec![0.0; buf_size],
            ring_pos: 0,
            note_state: NoteState::Idle,
            state_samples: 0,
            attack_valid_samples: 0,
            attack_missing_frames: 0,
            total_samples: 0,
            suppress_frequency: None,
            suppress_until: 0,
            pitch_history: [None; 2],
            pitch_history_idx: 0,
            attack_from_pitch_jump: false,
            legato_candidate: None,
            legato_candidate_frames: 0,
            prev_spectrum: None,
            // Slide state: keep last 8 frames of cents values
            slide_history: vec![0i16; 8],
            slide_history_idx: 0,
            slide_velocity_decay: 0.9,
            // Vibrato state: buffer ~500ms of hop-spaced cents values.
            vibrato_buffer: Vec::with_capacity(vibrato_capacity),
            vibrato_buffer_idx: 0,
            vibrato_detected: false,
            vibrato_rate_hz: 0.0,
            vibrato_depth_cents: 0.0,
            // Pressure / NoteOff velocity state
            last_sustain_rms: 0.0,
            last_pressure: 0,
            note_onset_rms: 0.0,
            last_sent_pressure: 0,
            last_brightness: 0,
            single_cycle: super::single_cycle::SingleCycleDetector::new(sr, 75.0, 1400.0),
            early_pitch: None,
            hop_counter: 0,

